package com.bedlessfighter.necroManager.commands;
import com.bedlessfighter.necroManager.managers.MessageManager;import org.bukkit.Bukkit;import org.bukkit.command.*;import org.bukkit.entity.Player;import org.jetbrains.annotations.NotNull;import java.util.stream.Collectors;
public final class ListCommand implements CommandExecutor {public boolean onCommand(@NotNull CommandSender s,@NotNull Command c,@NotNull String label, @NotNull String[] a){if(a.length!=0){MessageManager.sendRaw(s,MessageManager.prefix()+" &cUsage: /list");return true;}String names=Bukkit.getOnlinePlayers().stream().map(Player::getName).sorted(String.CASE_INSENSITIVE_ORDER).collect(Collectors.joining("&7, &f"));MessageManager.sendRaw(s,MessageManager.color(MessageManager.configured("messages.list","&aOnline (&f%count%&a): &f%players%").replace("%count%",Integer.toString(Bukkit.getOnlinePlayers().size())).replace("%players%",names.isEmpty()?"&7none":names)));return true;}}